 areas={}
 for orientation,txt,process,logo,route in [('desktop',text_d,[.40,.34,.56,.57],[.55,.42,.34,.12],[.38,.76,.60,.17]),('mobile',text_m,[.08,.42,.84,.47],[.20,.48,.61,.09],[.77,.40,.18,.52])]:
  regions=[{'id':k,'role':'text_allowed','rect':v} for k,v in txt.items()]+[{'id':'process','role':'protect_object','rect':process},{'id':'logo','role':'protect_logo','rect':logo},{'id':'route','role':'protect_route','rect':route},{'id':'header','role':'ui_interference','rect':[0,0,1,.085]},{'id':'bottom','role':'ui_interference','rect':[0,.94,1,.06]}]
